using Microsoft.EntityFrameworkCore;

// Cosmos DB EF Core 9 fixes for existing documents.
// Apply these changes to your separate Cosmos DB project.

class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Fix 1: EF Core 9 renamed the default discriminator from "Discriminator"
        // to "$type". Existing documents still use "Discriminator", so explicitly
        // configure the old property name.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Fix 2: EF Core 9 changed the id format from "EntityType|Key" to just
        // "Key". Existing documents still use the old compound format. Preserve
        // it so point-reads continue to work.
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }

    // Fix 3: Cosmos DB provider no longer supports synchronous I/O.
    // All sync calls (SaveChanges, ToList, First, etc.) must become async.

    // BEFORE (breaks in EF Core 9):
    //   var sessions = db.Sessions.ToList();
    //   db.SaveChanges();
    //
    // AFTER:
    //   var sessions = await db.Sessions.ToListAsync();
    //   await db.SaveChangesAsync();
}

class Session
{
    public string Id { get; set; } = default!;
    public string Title { get; set; } = default!;
}

